where 1=1

		and cdpl_llave = #{llaveTabla}


		and cdpl_tipo = #{tipo}


		and cdpl_padre = #{padre}


		and cdpl_estado = #{estado}


		and cdpl_nombre = #{nombre}


		and cdpl_consecutivo = #{consecutivo}


		and cdpl_codigo = #{codigo}


		and cdpl_proceso = #{proceso}


		and (upper(cdpl_nombre) like upper('%' || #{filtroParametro} || '%') or cdpl_codigo =  #{filtroParametro})

mapper.update:
update documentoplantilla_dplp
	set cdpl_tipo = #{tipo},
		cdpl_padre = #{padre}
where cdpl_llave = #{llaveTabla}
